# Collect the judgements of all reproduction scripts into
# inst/reproduce/results/SUMMARY.md (do not edit SUMMARY.md by hand).
# Run from the package root after the reproduction scripts:
#   source("inst/reproduce/summarize.R")

files <- sort(list.files("inst/reproduce/results",
                         pattern = "^reproduce_.*\\.csv$", full.names = TRUE))
levels_j <- c("PASS", "EXPLAINED", "FAIL", "INFO")
out <- c("# Summary of the reproduction results", "",
         "Generated by `inst/reproduce/summarize.R` from the CSV files in",
         "this folder.", "",
         "| Results file | PASS | EXPLAINED | FAIL | INFO |",
         "|---|---|---|---|---|")
details <- character(0)
for (f in files) {
  tab <- utils::read.csv(f, stringsAsFactors = FALSE)
  cnt <- table(factor(tab$judgement, levels = levels_j))
  out <- c(out, sprintf("| %s | %d | %d | %d | %d |", basename(f),
                        cnt[["PASS"]], cnt[["EXPLAINED"]], cnt[["FAIL"]],
                        cnt[["INFO"]]))
  sel <- tab[tab$judgement %in% c("EXPLAINED", "FAIL"), ]
  for (i in seq_len(nrow(sel))) {
    details <- c(details,
                 sprintf("- %s (%s, %s): published %s, reproduced %s. %s",
                         sel$id[i], basename(f), sel$judgement[i],
                         format(sel$published[i], digits = 4),
                         format(sel$reproduced[i], digits = 4),
                         sel$note[i]))
  }
}
out <- c(out, "", "## Items that are not PASS or INFO", "",
         if (length(details) > 0L) details else "None.")
writeLines(out, "inst/reproduce/results/SUMMARY.md")
cat(out, sep = "\n")
